/// @file tests/cpu/vib/test_thermochem_vs_pyscf.cpp
/// @brief Thermochemistry parity test: cpu::vib::Thermochem vs PySCF
///        pyscf.hessian.thermo.thermo (spec phase4-vibrations-03,
///        ac-001 / ac-002 / ac-003).
///
/// The reference data (ZPE, thermal Gibbs correction, per-component
/// entropies) is checked in as pyscf_thermo_data.h, generated by
/// a one-off PySCF run (generator removed; values are pinned) from a
/// genuine PySCF 2.x run (provenance in pyscf_thermo_references.json).
/// The C++ `cpu::vib::Thermochem` and PySCF `thermo()` operate on the
/// SAME optimized geometry and the SAME harmonic frequencies, so the
/// only gap measured here is the thermochemistry port itself.

#include <gtest/gtest.h>

#include <cmath>
#include <string>
#include <vector>

#include "atomiverse/core/mat3.h"
#include "atomiverse/cpu/frame/frame.h"
#include "atomiverse/cpu/scf/integrals.h"
#include "atomiverse/cpu/scf/scf_evaluator.h"
#include "atomiverse/cpu/scf/scf_types.h"
#include "atomiverse/cpu/vib/hessian.h"
#include "atomiverse/cpu/vib/hessian_result.h"
#include "atomiverse/cpu/vib/nist_constants.h"
#include "atomiverse/cpu/vib/thermochem.h"
#include "atomiverse/facade/component_role.h"
#include "atomiverse/facade/stage.h"

#include "reference/pyscf_thermo_data.h"

using namespace ATV;

namespace {

/// @brief 1 Hartree expressed in electron-volts (PySCF-consistent).
///
/// Named distinctly from `ATV::units::kHartreeInEv`: `using namespace ATV;` above
/// makes a same-named local an ambiguous reference, and this test deliberately wants the
/// NIST value PySCF uses, not the engine's own.
const double kNistHartree2eV = cpu::vib::nist::HARTREE2EV;

/// @brief 1 Hartree expressed in kilojoules per mole.
///
/// `HARTREE2J * AVOGADRO` [J/mol] divided by 1000 -> kJ/mol.
const double kHartree2kJmol =
    cpu::vib::nist::HARTREE2J * cpu::vib::nist::AVOGADRO * 1.0e-3;

/// @brief Build a cpu::Frame from a checked-in reference molecule.
/// @param ref Reference molecule (geometry + atomic numbers).
/// @return Frame with positions in Angstrom, atomic numbers in `type`.
cpu::Frame make_frame(const pyscf_thermo_ref::RefThermo& ref) {
    const int n = ref.natoms;
    cpu::Frame f(n);
    for (int i = 0; i < n; ++i) {
        f.span(ATV::kAtom_x)[i] = ref.geom[i].x;
        f.span(ATV::kAtom_y)[i] = ref.geom[i].y;
        f.span(ATV::kAtom_z)[i] = ref.geom[i].z;
        f.span(ATV::kAtom_type)[i] = ref.geom[i].Z;
    }
    f.simbox = ATV::cpu::Box::cubic(100.0);
    return f;
}

/// @brief Tight RHF config so each displaced SCF is gradient-stationary.
/// @param ints Integral pack supplying the electron count.
/// @return RHF SCFConfig with `tol = 1e-12`, `conv_tol_grad = 1e-9`.
cpu::scf::SCFConfig tight_rhf_config(const cpu::scf::IntegralPack& ints) {
    auto cfg = cpu::scf::rhf_config(ints, /*tol=*/1e-12);
    cfg.conv_tol_grad = 1e-9;
    return cfg;
}

/// @brief Run cpu::vib::Hessian with a Thermochem component registered.
/// @param ref Reference molecule.
/// @return HessianResult with frequencies + thermochemistry populated.
cpu::vib::HessianResult run_thermo(const pyscf_thermo_ref::RefThermo& ref) {
    cpu::Frame frame = make_frame(ref);
    auto ints = cpu::scf::build_integrals(frame, cpu::scf::BasisSet::Pople631G);
    auto cfg = tight_rhf_config(ints);

    cpu::vib::Thermochem::Config tc;
    tc.temperature = ref.temperature_K;
    tc.pressure = ref.pressure_Pa;
    tc.multiplicity = ref.multiplicity;
    tc.symmetry_number = ref.symmetry_number;

    cpu::vib::Hessian driver{tc};
    driver.on(ATV::vib::Phase::force)
        .add(cpu::scf::SCF{cfg, cpu::scf::BasisSet::Pople631G});
    driver.build();
    return driver.run(frame);
}

/// @brief Look up a reference molecule by name.
const pyscf_thermo_ref::RefThermo& ref(const char* name) {
    for (const auto& m : pyscf_thermo_ref::reference())
        if (std::string(m.name) == name)
            return m;
    throw std::runtime_error(std::string("no thermo reference for ") + name);
}

} // namespace

// ── ac-001: ZPE matches PySCF within 0.001 eV ───────────────────────────

TEST(VibThermochemVsPyscf, ZeroPointEnergy) {
    for (const char* name : {"h2o", "nh3", "ch4"}) {
        const auto& r = ref(name);
        const auto result = run_thermo(r);

        const double dev_eV =
            std::abs(result.zpe - r.zpe_hartree) * kNistHartree2eV;
        std::cout << "[ zpe ] " << name << " atomiverse=" << result.zpe
                  << " Ha  pyscf=" << r.zpe_hartree << " Ha  dev=" << dev_eV
                  << " eV\n";
        EXPECT_LE(dev_eV, 0.001)
            << name << ": ZPE deviation vs PySCF = " << dev_eV
            << " eV (tolerance 0.001 eV)";

        // Electronic-energy-independent identity: E_0K - E0 == ZPE.
        // Thermochem reports U/H/G with E0 = 0, so u_tot at T=0 == ZPE.
        // The simplest surfaced form here: g_thermal carries no E0.
    }
}

// ── ac-002: thermal Gibbs correction within 0.5 kJ/mol ──────────────────

TEST(VibThermochemVsPyscf, GibbsThermalCorrection) {
    for (const char* name : {"h2o", "nh3", "ch4"}) {
        const auto& r = ref(name);
        const auto result = run_thermo(r);

        const double dev_kJ =
            std::abs(result.g_thermal - r.g_thermal_hartree) * kHartree2kJmol;
        std::cout << "[ gibbs ] " << name << " atomiverse=" << result.g_thermal
                  << " Ha  pyscf=" << r.g_thermal_hartree
                  << " Ha  dev=" << dev_kJ << " kJ/mol\n";
        EXPECT_LE(dev_kJ, 0.5)
            << name << ": G_tot - E0 deviation vs PySCF = " << dev_kJ
            << " kJ/mol (tolerance 0.5 kJ/mol)";
    }
}

// ── ac-003: per-component entropies match PySCF on H2O ──────────────────

TEST(VibThermochemVsPyscf, PerComponentEntropiesWater) {
    const auto& r = ref("h2o");
    const auto result = run_thermo(r);

    // HessianResult carries the per-component entropy breakdown so a
    // failing S_tot can be traced to the partition function at fault.
    // Tight per-component tolerance: 1e-8 Eh/K (~3e-3 J/mol/K).
    const double tol = 1.0e-8;

    EXPECT_NEAR(result.s_trans, r.s_trans, tol)
        << "S_trans (Sackur-Tetrode) mismatch vs PySCF";
    EXPECT_NEAR(result.s_rot, r.s_rot, tol)
        << "S_rot (rigid-rotor) mismatch vs PySCF";
    EXPECT_NEAR(result.s_vib, r.s_vib, tol)
        << "S_vib (harmonic-oscillator) mismatch vs PySCF";
    EXPECT_NEAR(result.s_tot, r.s_tot, tol)
        << "S_tot aggregation mismatch vs PySCF";

    std::cout << "[ S_components ] h2o  S_trans=" << result.s_trans
              << "  S_rot=" << result.s_rot << "  S_vib=" << result.s_vib
              << " Eh/K\n";
}

// ── Provenance: reference data is from a genuine PySCF run ───────────────

TEST(VibThermochemVsPyscf, ReferenceProvenance) {
    EXPECT_STRNE(pyscf_thermo_ref::kPyscfVersion, "");
    EXPECT_EQ(pyscf_thermo_ref::reference().size(), 3u);
}

// ── ac-006: Thermochem is tagged as an Observer ─────────────────────────

TEST(VibThermochemVsPyscf, ComponentRoleIsObserver) {
    cpu::vib::Thermochem tc{cpu::vib::Thermochem::Config{}};
    EXPECT_EQ(tc.role(), ComponentRole::Observer);
}
